mapper.select:
SELECT gzid AS id, gzdm AS gzzdm, gzmc AS gzzmc, pym, '' AS gzzlx, '' AS gzzlxmc, '' AS his_ksdm, 1 AS xh, COALESCE(sybz, 1) AS sybz FROM sys_gzzd WHERE 1=1 AND gzdm = #{gzzdm}
AND (gzmc LIKE CONCAT('%',#{keyword},'%') OR pym LIKE CONCAT('%',#{keyword},'%'))
AND sybz = #{sybzVal} ORDER BY gzdm

mapper.update:
UPDATE sys_gzzd
SET gzmc=#{gzmc}, pym=#{pym}, gzzlx=#{gzzlx}, xh=#{xh}, sybz=#{sybz}
WHERE gzdm=#{gzdm}
